ALTER TABLE public.game_state ADD COLUMN garden_spent integer NOT NULL DEFAULT 0;
CREATE TABLE public.garden_inventory (user_id uuid NOT NULL, item_id text NOT NULL, quantity integer NOT NULL DEFAULT 0 CHECK (quantity >= 0), PRIMARY KEY(user_id,item_id));
GRANT SELECT ON public.garden_inventory TO authenticated;
GRANT ALL ON public.garden_inventory TO service_role;
ALTER TABLE public.garden_inventory ENABLE ROW LEVEL SECURITY;
CREATE POLICY garden_inventory_self ON public.garden_inventory FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.garden_plants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL, species text NOT NULL CHECK(species IN ('seed_rose','seed_mango','seed_sunflower','seed_paper')), slot integer NOT NULL CHECK(slot BETWEEN 0 AND 39), planted_at timestamptz NOT NULL DEFAULT now(), watered_at timestamptz, grow_days integer NOT NULL DEFAULT 2);
GRANT SELECT ON public.garden_plants TO authenticated;
GRANT ALL ON public.garden_plants TO service_role;
ALTER TABLE public.garden_plants ENABLE ROW LEVEL SECURITY;
CREATE INDEX garden_plants_owner ON public.garden_plants(owner_id);
CREATE FUNCTION public.garden_can_share(target uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND (target=auth.uid() OR EXISTS(SELECT 1 FROM public.friends f WHERE f.status='accepted' AND ((f.user_id=auth.uid() AND f.friend_id=target) OR (f.friend_id=auth.uid() AND f.user_id=target)))); $$;
REVOKE ALL ON FUNCTION public.garden_can_share(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.garden_can_share(uuid) TO authenticated;
CREATE POLICY garden_friend_read ON public.garden_plants FOR SELECT TO authenticated USING(public.garden_can_share(owner_id));
CREATE FUNCTION public.garden_preserve_spending() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND NEW.garden_spent < OLD.garden_spent THEN NEW.money=GREATEST(0, NEW.money-(OLD.garden_spent-NEW.garden_spent)); NEW.garden_spent=OLD.garden_spent; END IF; RETURN NEW; END; $$;
CREATE TRIGGER preserve_garden_spending BEFORE UPDATE ON public.game_state FOR EACH ROW EXECUTE FUNCTION public.garden_preserve_spending();
CREATE FUNCTION public.garden_purchase(item text, amount integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid=auth.uid(); cost integer; balance integer; spent integer; BEGIN IF uid IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; IF amount < 1 OR amount > 99 THEN RAISE EXCEPTION 'Invalid quantity'; END IF; cost=CASE item WHEN 'seed_rose' THEN 18 WHEN 'seed_mango' THEN 30 WHEN 'seed_sunflower' THEN 12 WHEN 'seed_paper' THEN 12 WHEN 'watering_use' THEN 5 ELSE NULL END; IF cost IS NULL THEN RAISE EXCEPTION 'Invalid item'; END IF; UPDATE public.game_state SET money=money-cost*amount, garden_spent=garden_spent+cost*amount WHERE user_id=uid AND money>=cost*amount RETURNING money,garden_spent INTO balance,spent; IF NOT FOUND THEN RAISE EXCEPTION 'Not enough coins'; END IF; INSERT INTO public.garden_inventory(user_id,item_id,quantity) VALUES(uid,item,amount) ON CONFLICT(user_id,item_id) DO UPDATE SET quantity=garden_inventory.quantity+amount; RETURN jsonb_build_object('money',balance,'garden_spent',spent); END; $$;
REVOKE ALL ON FUNCTION public.garden_purchase(text,integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.garden_purchase(text,integer) TO authenticated;
CREATE FUNCTION public.garden_plant(item text, cell integer) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid=auth.uid(); plant_id uuid; BEGIN IF uid IS NULL OR cell NOT BETWEEN 0 AND 39 OR item NOT IN ('seed_rose','seed_mango','seed_sunflower','seed_paper') THEN RAISE EXCEPTION 'Invalid planting'; END IF; PERFORM pg_advisory_xact_lock(81542); IF EXISTS(SELECT 1 FROM public.garden_plants WHERE slot=cell AND public.garden_can_share(owner_id)) THEN RAISE EXCEPTION 'This plot is occupied'; END IF; IF (SELECT count(*) FROM public.garden_plants WHERE owner_id=uid)>=12 THEN RAISE EXCEPTION 'Maximum 12 plants per player'; END IF; UPDATE public.garden_inventory SET quantity=quantity-1 WHERE user_id=uid AND item_id=item AND quantity>0; IF NOT FOUND THEN RAISE EXCEPTION 'Buy seeds first'; END IF; INSERT INTO public.garden_plants(owner_id,species,slot,grow_days) VALUES(uid,item,cell,CASE item WHEN 'seed_mango' THEN 4 WHEN 'seed_paper' THEN 3 ELSE 2 END) RETURNING id INTO plant_id; RETURN plant_id; END; $$;
REVOKE ALL ON FUNCTION public.garden_plant(text,integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.garden_plant(text,integer) TO authenticated;
CREATE FUNCTION public.garden_water(plant uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid=auth.uid(); p public.garden_plants; BEGIN SELECT * INTO p FROM public.garden_plants WHERE id=plant FOR UPDATE; IF NOT FOUND OR NOT public.garden_can_share(p.owner_id) THEN RAISE EXCEPTION 'Plant unavailable'; END IF; IF p.watered_at IS NOT NULL THEN RAISE EXCEPTION 'Already watered; growing'; END IF; UPDATE public.garden_inventory SET quantity=quantity-1 WHERE user_id=uid AND item_id='watering_use' AND quantity>0; IF NOT FOUND THEN RAISE EXCEPTION 'Buy a watering use first'; END IF; UPDATE public.garden_plants SET watered_at=now() WHERE id=plant; END; $$;
REVOKE ALL ON FUNCTION public.garden_water(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.garden_water(uuid) TO authenticated;
ALTER PUBLICATION supabase_realtime ADD TABLE public.garden_plants;